const { chromium } = require('playwright');

(async () => {
  console.log('🎭 Starting Computed Style Extraction Test');

  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext();
  const page = await context.newPage();

  try {
    console.log('🌐 Navigating to practice page...');
    await page.goto('https://practicetestautomation.com/practice-test-login/');

    // Wait for the submit button to be visible
    const submitButton = page.locator('#submit');
    await submitButton.waitFor();

    console.log('🔍 Extracting computed styles for the submit button...');

    // Using locator.evaluate to run code in the browser context
    const styles = await submitButton.evaluate((el) => {
      const computed = window.getComputedStyle(el);
      return {
        backgroundColor: computed.backgroundColor,
        color: computed.color,
        fontSize: computed.fontSize,
        fontWeight: computed.fontWeight
      };
    });

    console.log('📌 Extracted Styles:');
    console.log(`   Background Color: ${styles.backgroundColor}`);
    console.log(`   Text Color:       ${styles.color}`);
    console.log(`   Font Size:        ${styles.fontSize}`);
    console.log(`   Font Weight:      ${styles.fontWeight}`);

    // Simple assertion to verify we got actual values
    if (styles.backgroundColor && styles.backgroundColor !== '') {
      console.log('✅ SUCCESS: Computed styles extracted successfully.');
    } else {
      throw new Error('Failed to extract valid computed styles.');
    }

    console.log('🏁 Test completed successfully.');
  } catch (error) {
    console.error('❌ Test failed:', error.message);
    process.exit(1);
  } finally {
    await browser.close();
  }
})();

